$entityNames = @('{{PDataProfiseeToProfiseeImport}}')
$problems = [System.Collections.Generic.List[string]]::new()
$entities = @(Get-Rows 'v1/Entities')
foreach ($d in $expected.domains.Keys) {
    $e = $entities | Where-Object { $_.identifier.name -eq $d }
    if (-not $e) { $problems.Add("domain $d missing"); continue }
    if ($e.identifier.id -ne $expected.domains[$d].id) { $problems.Add("domain $d id $($e.identifier.id), spec $($expected.domains[$d].id)") }
    $codes = @(Get-Rows "v1/Records/$d`?pageSize=1000" | ForEach-Object { $_.code } | Sort-Object)
    $want = @($expected.domains[$d].codes | Sort-Object)
    if (($codes -join '|') -ne ($want -join '|')) { $problems.Add("domain $d holds $($codes.Count) rows, spec $($want.Count) (codes differ)") }
}
$attributes = @(Get-Rows 'v1/Attributes')
foreach ($n in $entityNames) {
    if (-not ($entities | Where-Object { $_.identifier.name -eq $n })) { $problems.Add("entity $n missing"); continue }
    $own = @($attributes | Where-Object { $_.identifier.entityId.name -eq $n -and -not $_.isSystem -and $_.identifier.name -notin 'Code', 'Name' })
    if ($own.Count -ne $expected.attributes) { $problems.Add("entity $n has $($own.Count) attributes, spec $($expected.attributes)") }
    foreach ($a in $own) {
        $want = $expected.domainAttributes[$a.identifier.name]
        if ($want -and $a.domainEntityId.id -ne $want) { $problems.Add("$n.$($a.identifier.name) points at $($a.domainEntityId.name) $($a.domainEntityId.id), spec $want") }
    }
}
if ($problems.Count) { throw "Model verify failed ($($problems.Count)): $(($problems | Select-Object -First 25) -join '; ')" }
